// These tests run without a Java runtime or network access.
use std::collections::BTreeMap;
use std::path::PathBuf;
use std::process::Command;

struct Scratch(PathBuf);
impl Scratch {
    fn new(name: &str) -> Self {
        let dir = std::env::temp_dir().join(format!("jfrconv-{}-{}", name, std::process::id()));
        std::fs::create_dir_all(&dir).unwrap();
        Self(dir)
    }
    fn fixture(&self) -> PathBuf {
        let path = self.0.join("input.jfr");
        std::fs::write(&path, include_bytes!("fixtures/mixed.jfr")).unwrap();
        path
    }
}
impl Drop for Scratch {
    fn drop(&mut self) {
        let _ = std::fs::remove_dir_all(&self.0);
    }
}
fn canonical(text: &str) -> BTreeMap<String, u64> {
    let mut map = BTreeMap::new();
    for line in text.lines().filter(|line| !line.is_empty()) {
        let (stack, value) = line.rsplit_once(' ').expect("collapsed stack and counter");
        *map.entry(stack.to_owned()).or_default() += value.parse::<u64>().unwrap();
    }
    map
}
