#[test]
fn matches_v41_collapsed_golden_outputs() {
    let scratch = Scratch::new("golden");
    let input = scratch.fixture();
    for &(name, flags, expected) in CASES {
        let output = scratch.0.join(format!("{}.collapsed", name));
        let result = Command::new(env!("CARGO_BIN_EXE_jfrconv"))
            .args(flags)
            .args(["-o", "collapsed"])
            .arg(&input)
            .arg(&output)
            .output()
            .unwrap();
        assert!(
            result.status.success(),
            "{}: {}",
            name,
            String::from_utf8_lossy(&result.stderr)
        );
        let actual = std::fs::read_to_string(output).unwrap();
        assert_eq!(canonical(&actual), canonical(expected), "{}", name);
    }
}

#[test]
fn filters_samples_by_span_tag() {
    let scratch = Scratch::new("span");
    let input = scratch.fixture();
    let output = scratch.0.join("span.collapsed");
    let result = Command::new(env!("CARGO_BIN_EXE_jfrconv"))
        .args(["--cpu", "--tag", "request-.*", "-o", "collapsed"])
        .arg(input)
        .arg(&output)
        .output()
        .unwrap();
    assert!(
        result.status.success(),
        "{}",
        String::from_utf8_lossy(&result.stderr)
    );
    let stacks = canonical(&std::fs::read_to_string(output).unwrap());
    assert_eq!(stacks.values().sum::<u64>(), 4);
    assert!(stacks.keys().all(|stack| stack.contains("Worker.work")));
}

#[test]
fn rejects_invalid_and_truncated_inputs_without_panicking() {
    let scratch = Scratch::new("corrupt");
    let raw = include_bytes!("fixtures/mixed.jfr");
    let mut invalid_magic = raw.to_vec();
    invalid_magic[..4].copy_from_slice(b"NOPE");
    let mut zero_size = raw.to_vec();
    zero_size[68] = 0;
    let variants = vec![
        Vec::new(),
        raw[..32].to_vec(),
        raw[..raw.len() - 8].to_vec(),
        invalid_magic,
        zero_size,
    ];
    for (index, bytes) in variants.into_iter().enumerate() {
        let input = scratch.0.join(format!("bad{}.jfr", index));
        std::fs::write(&input, bytes).unwrap();
        let output = scratch.0.join("out.collapsed");
        std::fs::write(&output, b"existing result\n").unwrap();
        let result = Command::new(env!("CARGO_BIN_EXE_jfrconv"))
            .args(["-o", "collapsed"])
            .arg(input)
            .arg(&output)
            .output()
            .unwrap();
        assert!(
            !result.status.success(),
            "corrupt case {} unexpectedly accepted",
            index
        );
        assert!(!String::from_utf8_lossy(&result.stderr).contains("panicked"));
        assert_eq!(std::fs::read(&output).unwrap(), b"existing result\n");
    }
}

#[test]
fn converts_lock_ticks_with_each_chunks_clock_rate() {
    let scratch = Scratch::new("clock");
    let input = scratch.0.join("scaled-clock.jfr");
    let mut raw = include_bytes!("fixtures/mixed.jfr").to_vec();
    let mut offset = 0usize;
    while offset < raw.len() {
        let size = u64::from_be_bytes(raw[offset + 8..offset + 16].try_into().unwrap()) as usize;
        raw[offset + 56..offset + 64].copy_from_slice(&10_000_000u64.to_be_bytes());
        offset += size;
    }
    std::fs::write(&input, raw).unwrap();
    let output = scratch.0.join("clock.collapsed");
    let result = Command::new(env!("CARGO_BIN_EXE_jfrconv"))
        .args(["--lock", "--total", "-o", "collapsed"])
        .arg(input)
        .arg(&output)
        .output()
        .unwrap();
    assert!(
        result.status.success(),
        "{}",
        String::from_utf8_lossy(&result.stderr)
    );
    let stacks = canonical(&std::fs::read_to_string(output).unwrap());
    assert_eq!(stacks.values().sum::<u64>(), 10_000_000);
}

#[test]
fn leak_analysis_orders_events_and_keeps_original_chunk_stack() {
    let scratch = Scratch::new("leak-order");
    let input = scratch.0.join("leaks.jfr");
    std::fs::write(&input, include_bytes!("fixtures/leak-order.jfr")).unwrap();
    let output = scratch.0.join("leaks.collapsed");
    let result = Command::new(env!("CARGO_BIN_EXE_jfrconv"))
        .args([
            "--nativemem",
            "--leak",
            "--tail",
            "0",
            "--total",
            "-o",
            "collapsed",
        ])
        .arg(input)
        .arg(&output)
        .output()
        .unwrap();
    assert!(
        result.status.success(),
        "{}",
        String::from_utf8_lossy(&result.stderr)
    );
    let stacks = canonical(&std::fs::read_to_string(output).unwrap());
    assert_eq!(stacks.values().sum::<u64>(), 4096);
    assert!(stacks
        .keys()
        .all(|stack| stack.starts_with("original/Main.run")));
    assert!(stacks
        .keys()
        .all(|stack| stack.contains("original/Worker.work")));
}

#[test]
fn current_span_api_filter_crosses_chunks_and_reads_constant_pool_tag() {
    let scratch = Scratch::new("cross-span");
    let input = scratch.0.join("cross-span.jfr");
    std::fs::write(&input, include_bytes!("fixtures/cross-span.jfr")).unwrap();
    let output = scratch.0.join("cross-span.collapsed");
    let result = Command::new(env!("CARGO_BIN_EXE_jfrconv"))
        .args([
            "--cpu",
            "--latency",
            "100",
            "--tag",
            "cross-request",
            "-o",
            "collapsed",
        ])
        .arg(input)
        .arg(&output)
        .output()
        .unwrap();
    assert!(
        result.status.success(),
        "{}",
        String::from_utf8_lossy(&result.stderr)
    );
    let stacks = canonical(&std::fs::read_to_string(output).unwrap());
    assert_eq!(stacks.values().sum::<u64>(), 2);
    assert_eq!(stacks.len(), 2);
    assert!(stacks
        .keys()
        .any(|stack| stack.starts_with("before/Main.run")));
    assert!(stacks
        .keys()
        .any(|stack| stack.starts_with("after/Main.run")));
}
